function isSafetyLabel(content){if(typeof content!=='string')return false;const lines=content.trim().split(/\n+/).map(x=>x.trim()).filter(Boolean);if(lines.length&&lines.every(line=>/^(?:(?:user|response|content)\s+safety|safety|label)\s*:\s*(?:safe|unsafe|unknown|[a-z0-9_, -]+)$/i.test(line)))return true;try{const value=JSON.parse(content);return value&&typeof value==='object'&&!Array.isArray(value)&&!value.answer&&Object.keys(value).length>0&&Object.keys(value).every(k=>/^(?:(?:user|response|content)[ _]safety|safety|label)$/i.test(k));}catch{return false;}}
const sessionsKey='question-garden-conversations-v1';let library={active:'first',conversations:[{...state,id:'first',title:'新对话',titleGenerated:false}]};
