function renderMessages(){renderHistory();const el=$('#messages');el.innerHTML=state.messages.map(m=>`<div class="msg ${m.role==='user'?'user':''}" id="${escape(m.id)}"><div class="who">${m.role==='user'?'你':'问迹 · '+(m.live?'AI 回答'+(m.elapsedMs?' · '+(m.elapsedMs/1000).toFixed(1)+' 秒':''):m.id.startsWith('new')?'历史原型提示':'对话摘要')}</div><div class="bubble">${escape(m.error?'这条旧回复来自安全检测模型，没有回答你的问题。请重新发送原问题。':m.text)}</div>${toolSources(m)}${organizationBadge(m)}${state.questions.some(q=>q.messageId===m.id)?'<div class="capture">↳ 已收进问题地图</div>':''}</div>`).join('');}
function topicPath(q){if(Array.isArray(q.path)&&q.path.length)return q.path;const text=q.title+' '+q.source;if(/口语|英语/.test(text))return ['其他探索','英语口语'];if(/模型|API|api|GPT|充值/.test(text))return ['问题梳理器','模型接入'];if(q.group==='产品设计')return ['问题梳理器','问题地图'];if(q.group==='使用条件'||q.group==='工具与模型')return ['开发工具'];if(q.group==='学习与探索')return ['基础认识'];return ['待归类'];}
function renderMap(){renderCollectionNotice();renderDeleteUndo();const keyword=$('#search').value.trim().toLowerCase();$('#mapPanel').classList.toggle('search-editing',document.activeElement===$('#search')||Boolean(keyword));const qs=state.questions.filter(q=>(q.title+' '+q.source+' '+(q.followups||[]).map(f=>f.text).join(' ')+' '+topicPath(q).join(' ')).toLowerCase().includes(keyword));const root={children:new Map(),questions:[]};for(const q of qs){let node=root;for(const name of topicPath(q)){if(!node.children.has(name))node.children.set(name,{children:new Map(),questions:[]});node=node.children.get(name);}node.questions.push(q);}function count(n){return n.questions.length+Array.from(n.children.values()).reduce((sum,c)=>sum+count(c),0);}function draw(n,prefix=''){return Array.from(n.children).map(([name,child])=>{const path=prefix+'/'+name;return '<details class="topic-branch" data-path="'+escape(path)+'" '+(openedBranches.has(path)||keyword||filter!=='all'?'open':'')+'><summary><span class="branch-arrow">▶</span><span>'+escape(name)+'</span><small>'+count(child)+' 个问题</small></summary><div class="topic-content">'+draw(child,path)+child.questions.map(q=>'<button class="q" data-id="'+escape(q.id)+'"><div class="qtop"><span class="qtitle">'+escape(q.title)+'</span></div><div class="relation">'+escape(q.type||'问题')+(q.followups?.length?' · '+q.followups.length+' 次追问':'')+'</div></button>').join('')+'</div></details>';}).join('');}$('#byTopic').classList.toggle('active',(!state.mapView||state.mapView==='topic'));$('#byTime').classList.toggle('active',state.mapView==='time');$('#byTopic').setAttribute('aria-pressed',String((!state.mapView||state.mapView==='topic')));$('#byTime').setAttribute('aria-pressed',String(state.mapView==='time'));$('#stagedView').classList.toggle('active',state.mapView==='staged');$('#stagedView').textContent='临时区'+(stagedItems().length?' ('+stagedItems().length+')':'');$('#recentView').classList.toggle('active',state.mapView==='recent');$('#favoritesView').classList.toggle('active',state.mapView==='favorites');$('#timeOrder').hidden=state.mapView!=='time';$('#timeOrder').value=state.timeOrder||'asc';$('#tree').innerHTML=(state.mapView==='staged'?renderStaged():state.mapView==='favorites'?renderFavorites(qs):keyword?renderQuestionResults(qs,false):state.mapView==='recent'?renderQuestionResults(qs,true):state.mapView==='time'?renderTimeline():QuestionGraph.render(root,state.title||'新对话',collapsedGraphTopics,Boolean(keyword||filter!=='all'),state.id))||'<div class="empty">'+(state.questions.length?'没有匹配的问题':'开始对话后，问题会逐步长成分支。')+'</div>';$('#mapTitle').textContent=state.title||'新对话';$('#conversationTitle').textContent=state.title||'新对话';}
function timelineEvents(){const events=[];const messageOrder=new Map(state.messages.map((m,i)=>[m.id,i]));state.questions.forEach((q,index)=>{const original=state.messages.find(m=>m.id===q.messageId);events.push({q,text:q.title,messageId:q.messageId,kind:'首次提问',time:original?.createdAt||q.createdAt,position:messageOrder.get(q.messageId)??state.messages.length+index,sub:0});(q.followups||[]).forEach((f,j)=>{const m=state.messages.find(m=>m.id===f.messageId);events.push({q,text:f.text,messageId:f.messageId,kind:'继续追问',time:m?.createdAt||f.createdAt,position:messageOrder.get(f.messageId)??state.messages.length+index,sub:j+1});});});events.sort((a,b)=>a.position-b.position||a.sub-b.sub);return events.map((event,i)=>({...event,number:i+1}));}
function renderTimeline(){const keyword=$('#search').value.trim().toLowerCase();let events=timelineEvents().filter(e=>(!keyword||(e.text+' '+e.q.title+' '+topicPath(e.q).join(' ')).toLowerCase().includes(keyword)));if(state.timeOrder==='desc')events=events.slice().reverse();if(!events.length)return '';return '<p class="timeline-note">已整理的问题与追问 · 按对话顺序排列<br>旧记录没有准确时间，以提问序号表示。</p><div class="question-timeline">'+events.map(e=>'<button class="timeline-event" data-id="'+escape(e.q.id)+'" data-event-message="'+escape(e.messageId||'')+'"><span class="event-number">'+String(e.number).padStart(2,'0')+'</span><span class="event-body"><span class="event-top"><span>'+e.kind+'</span><time>'+(e.time&&Number.isFinite(Date.parse(e.time))?escape(new Date(e.time).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})):'历史记录')+'</time></span><span class="event-title">'+escape(e.text)+'</span><span class="event-path">'+escape(topicPath(e.q).join(' › '))+'</span><span class="event-status">'+(e.kind==='继续追问'?'归属于「'+escape(e.q.title)+'」':'')+'</span></span></button>').join('')+'</div>';}
