function openConversation(id,mode='chat'){if(busy){toast('请等待当前回答完成后再切换');return;}const next=library.conversations.find(c=>c.id===id);if(!next)return;state=next;library.active=id;failedMessage=null;$('#chatError').hidden=true;filter='all';$('#search').value='';$('#input').value='';openedBranches.clear();collapsedGraphTopics.clear();QuestionGraph.reset();$('#mapPanel').classList.remove('graph-immersive');$('#workspace').dataset.mode=mode;$('#mapPanel').hidden=mode!=='map';$('#toggleMap').textContent=mode==='map'?'返回对话':'问题地图';sidebarMode=mode==='map'?'map':'history';window.Drawer.close();renderMessages();renderMap();save();$('#messages').scrollTop=$('#messages').scrollHeight;}
