$('#connectionForm').onsubmit=async e=>{e.preventDefault();const chosen=$('#provider').value;const chosenModel=$('#modelId').value.trim();if(!providers[chosen]||!chosenModel)return;if(chosen==='openrouter'&&(chosenModel==='openrouter/free'||/content-safety|guard|moderation/i.test(chosenModel))){$('#connectionStatus').textContent='请使用明确的聊天模型 ID，避免随机路由或安全检测模型。推荐：'+freeChatModel;return;}let savedKey='';try{savedKey=localStorage.getItem(chosen==='openrouter'?connectionStorageKey:connectionStorageKey+'-'+chosen)||'';}catch{}const candidate=$('#apiKey').value.trim()||(chosen===provider?apiKey:'')||savedKey;if(!candidate){$('#connectionStatus').textContent='请填写该服务商的 API Key。';return;}const button=$('#connectionForm button[type="submit"]');button.disabled=true;$('#connectionStatus').textContent='正在验证密钥…';try{const r=await fetch(providers[chosen].base+(chosen==='openrouter'?'/key':'/models'),{headers:{Authorization:'Bearer '+candidate},signal:AbortSignal.timeout(20000)});if(!r.ok)throw new Error(r.status===401?'密钥无效，请重新复制完整密钥。':'暂时无法验证，请稍后再试。');await CloudAccount.saveSettings(chosen,chosenModel,candidate);apiKey=candidate;provider=chosen;modelId=chosenModel;try{localStorage.setItem('question-garden-model-v1',JSON.stringify({provider,model:modelId}));const slot=provider==='openrouter'?connectionStorageKey:connectionStorageKey+'-'+provider;if($('#rememberKey').checked)localStorage.setItem(slot,candidate);else localStorage.removeItem(slot);}catch{toast('设备未允许保存密钥，本次连接仍可用');}$('#apiKey').value='';connectionLabel();$('#connectionStatus').textContent='配置已保存。模型可用性将在发送消息时确认。';$('#connection').close();toast('已连接，可以开始聊天');setTimeout(processOrganizationJobs,0);}catch(err){$('#connectionStatus').textContent=err.name==='TimeoutError'?'连接超时，请检查网络。':(err instanceof TypeError?'无法连接服务商，请检查网络。':err.message);}finally{button.disabled=false;}};
function apiMessages(){return [{role:'system',content:'你是问迹，一位耐心的中文学习伙伴。请直接用自然中文回答，不输出 JSON，不提及内部整理。回答简洁清晰，必要时追问。实时信息必须使用后端实际返回的工具结果，不得编造；工具失败或没有结果时明确说明。当前研究方向：'+state.title+'。最近摘要：'+(state.summary||'无')},...state.messages.filter(m=>!m.error).slice(-24).map(m=>({role:m.role==='user'?'user':'assistant',content:m.text.slice(0,6000)}))];}
function parseModelJson(content){try{return JSON.parse(content.trim().replace(/^```(?:json)?\s*/,'').replace(/\s*```$/,''));}catch{const start=content.indexOf('{'),end=content.lastIndexOf('}');if(start>=0&&end>start){try{return JSON.parse(content.slice(start,end+1));}catch{}}return null;}}
function mergeOrganized(conversation,data,message){if(!conversation.titleGenerated&&typeof data.conversation_title==='string'&&data.conversation_title.trim()){conversation.title=data.conversation_title.trim().slice(0,30);conversation.titleGenerated=true;}if(typeof data.summary==='string')conversation.summary=data.summary.slice(0,4000);if(Array.isArray(data.questions)){data.questions.slice(0,12).forEach((q,i)=>{if(!q||typeof q.title!=='string'||!q.title.trim())return;if((conversation.deletedQuestions||[]).some(item=>item.question.messageId===message.id&&item.question.title.trim()===q.title.trim()))return;const links=Array.isArray(q.related_ids)?q.related_ids.filter(id=>conversation.questions.some(x=>x.id===id)).slice(0,8):[];const existing=conversation.questions.find(x=>(x.messageId===message.id&&x.title.trim()===q.title.trim())||(q.mergeConfirmed===true&&typeof q.existing_id==='string'&&x.id===q.existing_id));if(!q.mergeConfirmed&&typeof q.existing_id==='string'&&conversation.questions.some(x=>x.id===q.existing_id)&&!links.includes(q.existing_id))links.push(q.existing_id);if(existing){existing.lastCollectedAt=new Date().toISOString();if(existing.messageId!==message.id){existing.followups=existing.followups||[];if(!existing.followups.some(f=>f.messageId===message.id))existing.followups.push({text:message.text,messageId:message.id,createdAt:message.createdAt});}existing.summary=typeof q.summary==='string'?q.summary.slice(0,2000):existing.summary;if(existing.status==='待探索'&&q.status==='已讨论')existing.status='已讨论';return;}conversation.questions.push({collectedAt:new Date().toISOString(),lastCollectedAt:new Date().toISOString(),path:Array.isArray(q.path)?q.path.filter(x=>typeof x==='string'&&x.trim()).slice(0,3).map(x=>x.slice(0,40)):[],type:['概念','比较','方法','设计','可行性'].includes(q.type)?q.type:'问题',id:message.id+'q'+i,title:q.title.slice(0,1000),group:categories.includes(q.group)?q.group:'待归类',status:q.status==='已讨论'?'已讨论':'待探索',source:message.text,messageId:message.id,createdAt:message.createdAt,links,relation:typeof q.relation==='string'?q.relation.slice(0,500):'AI 整理 · 可手动修正',summary:typeof q.summary==='string'?q.summary.slice(0,2000):''});});}}
function applyAnswer(content,message){if(isSafetyLabel(content))throw new Error('模型返回了安全检测标签，没有正常作答。');const data=parseModelJson(content);const structured=data&&typeof data.answer==='string'&&data.answer.trim();const reply={id:message.id+'reply',role:'assistant',text:structured?data.answer:content,createdAt:new Date().toISOString(),live:true,organizeStatus:'unselected',collectionChoice:'unselected'};state.messages.push(reply);}
function startWaiting(){
 const started=Date.now();const node=document.createElement('div');node.className='waiting-message';node.id='waitingMessage';node.innerHTML='<div class="waiting-icon" aria-hidden="true"><img src="tall-nut.png" alt=""></div><div><div class="waiting-title" role="status">正在思考</div><div class="waiting-note">正在等待模型回答</div></div><span class="waiting-time" aria-label="已等待时间">0 秒</span>';
 $('#messages').appendChild(node);$('#messages').setAttribute('aria-busy','true');$('#messages').scrollTop=$('#messages').scrollHeight;
 const update=()=>{const seconds=Math.floor((Date.now()-started)/1000);node.querySelector('.waiting-time').textContent=seconds+' 秒';node.querySelector('.waiting-note').textContent=seconds>=45?'等待较久，模型可能繁忙；超时后可重试':seconds>=15?'模型仍在处理中，请稍候':'正在等待模型回答';};
 const timer=setInterval(update,1000);
 return ()=>{clearInterval(timer);node.remove();$('#messages').setAttribute('aria-busy','false');return Date.now()-started;};
}
function readableApiError(status,data){const error=data?.error||{};const raw=[error.message,typeof error.metadata?.raw==='string'?error.metadata.raw:'',error.metadata?.limit_source].filter(Boolean).join(' | ');const safe=raw.split(apiKey||'__empty_key__').join('[密钥已隐藏]').slice(0,1500);$('#errorRaw').textContent='HTTP '+status+(safe?' · '+safe:'');if(status===429){if(/per.day|daily|free.model.daily|day.limit|requests.per.day/i.test(raw))return '今日免费请求次数已达上限，请等待额度重置。';if(/upstream|provider.*rate.limit|temporarily.rate.limit/i.test(raw))return '这个免费模型当前拥挤或被上游限流，不代表你的每日额度用完。';if(/per.minute|minute.limit|requests.per.min/i.test(raw))return '短时间请求过多，触发每分钟限制，请稍后再试。';return '请求被限流（429），暂不能确定是每日额度还是模型拥挤。可点“查看额度 / 原因”。';}return status===401?'密钥已失效，请重新连接 AI。':status===402?'服务拒绝了当前额度请求（402），请查看服务返回详情。':status===403?'服务拒绝访问，请检查账号或地区可用性。':status===404?'当前模型或符合参数的服务暂不可用，请在模型与 API 中更换聊天模型。':'模型服务出错（'+status+'），请查看返回详情。';}
async function checkQuota(){if(provider!=='openrouter'){$('#quotaResult').textContent='该入口用于 OpenRouter。其他服务商请在其控制台查询额度。';return;}if(!apiKey){$('#quotaResult').textContent='请先连接 OpenRouter。';return;}$('#checkQuota').disabled=true;$('#quotaResult').textContent='正在读取账户免费额度…';try{const r=await fetch('https://openrouter.ai/api/v1/key',{headers:{Authorization:'Bearer '+apiKey},signal:AbortSignal.timeout(20000)});const result=await r.json();if(!r.ok||result.error)throw new Error('无法读取，请检查连接或前往 OpenRouter 控制台。');const q=result.data?.free_model_daily_requests;if(q&&typeof q.remaining==='number'){$('#quotaResult').textContent='今日免费请求：已用 '+(q.used??'未知')+' / 上限 '+(q.limit??'未知')+'，剩余 '+q.remaining+' 次。'+(q.remaining>0?'还有额度；刚才若为 429，可能是每分钟限制或模型上游拥挤。':'今日额度已用完，请等待重置。');}else{$('#quotaResult').textContent='账户验证通过，但服务未返回每日免费次数，无法据此判断是否用完。请查看 OpenRouter 控制台。';}}catch(e){$('#quotaResult').textContent=e.name==='TimeoutError'?'读取额度超时，请稍后再试。':e.message;}finally{$('#checkQuota').disabled=false;}}
$('#checkQuota').onclick=checkQuota;$('#errorQuota').onclick=()=>{$('#connection').showModal();checkQuota();};
function readModelAnswer(data,message){const choice=data.choices?.[0];const finish=choice?.finish_reason;const content=choice?.message?.content;const hasReasoning=typeof choice?.message?.reasoning_content==='string'&&Boolean(choice.message.reasoning_content.trim());if(finish==='length'||typeof content!=='string'||!content.trim()){const diagnostic={model:data.model||modelId,finish_reason:finish||'unknown',has_content:typeof content==='string'&&Boolean(content.trim()),has_reasoning:hasReasoning,completion_tokens:data.usage?.completion_tokens??null};$('#errorRaw').textContent=JSON.stringify(diagnostic,null,2);if(finish==='length')throw new Error('回答达到输出长度上限，正文可能尚未生成完整。请重试；本次没有保存不完整回答。');if(finish==='content_filter')throw new Error('服务没有提供正文（返回 content_filter）。可修改问题后重试。');if(hasReasoning)throw new Error('服务只返回了思考内容，没有最终回答。问题已保留，可稍后重试。');throw new Error(provider==='deepseek'?'DeepSeek 本次返回了空正文，问题已保留。可稍后重试，不会重复添加提问。':'模型未返回正文，请查看服务返回详情后重试。');}return content;}
async function respond(message){const stopWaiting=startWaiting();busy=true;sendButton.disabled=true;sendButton.textContent='思考中…';$('#chatError').hidden=true;$('#retry').textContent='重试这条消息';$('#errorRaw').textContent='';$('#retry').disabled=true;try{const r=await fetch(providers[provider].base+'/chat/completions',{method:'POST',headers:{Authorization:'Bearer '+apiKey,'Content-Type':'application/json'},body:JSON.stringify({model:modelId,...(provider==='openrouter'?{provider:{require_parameters:true}}:{}),...(provider==='deepseek'?{thinking:{type:'disabled'}}:{}),messages:apiMessages(),app_tools:{mode:'auto',timezone:browserTimezone()},max_tokens:3000}),signal:AbortSignal.timeout(90000)});let data;try{data=await r.json();}catch{throw new Error('服务返回异常，请稍后重试。');}if(!r.ok||data.error){throw new Error(readableApiError(r.status,data));}const content=readModelAnswer(data,message);if(typeof data.model==='string'&&/content-safety|guard|moderation/i.test(data.model))throw new Error('服务返回了安全检测模型的结果，请切换聊天模型后重试。');applyAnswer(content,message);const reply=state.messages.find(m=>m.id===message.id+'reply');if(reply){reply.model=typeof data.model==='string'?data.model:modelId;reply.tools=Array.isArray(data.app_tools)?data.app_tools:[];}failedMessage=null;save();renderMessages();renderMap();renderSummary();$('#messages').scrollTop=$('#messages').scrollHeight;}catch(err){failedMessage=message;$('#errorText').textContent=err.name==='TimeoutError'?'等待回答超时。消息已保留，重试可能再次消耗免费次数。':err instanceof TypeError?'网络连接失败。消息已保留，请检查网络后重试。':err.message;$('#retry').textContent=message.retryWithoutJson?'重试（兼容模式）':'重试这条消息';$('#chatError').hidden=false;}finally{const elapsed=stopWaiting();const reply=state.messages.find(m=>m.id===message.id+'reply');if(reply){reply.elapsedMs=elapsed;save();renderMessages();$('#messages').scrollTop=$('#messages').scrollHeight;}busy=false;sendButton.disabled=false;sendButton.textContent='发送 ↑';$('#retry').disabled=false;}}
$('#form').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;if(!apiKey){$('#connection').showModal();return;}if(failedMessage){toast('请先重试上一条未完成的消息');return;}const text=$('#input').value.trim();if(!text)return;const message={id:'new'+Date.now(),role:'user',text,createdAt:new Date().toISOString()};state.messages.push(message);if(!state.titleGenerated&&state.title==='新对话')state.title=text.slice(0,20);$('#input').value='';$('#input').style.height='auto';save();renderMessages();$('#messages').scrollTop=$('#messages').scrollHeight;await respond(message);});
