function renderHistory(){const map=sidebarMode==='map';$('#listTitle').textContent=map?'选择对话，打开对应地图':'对话记录';document.querySelectorAll('#sidebar button[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===sidebarMode);b.setAttribute('aria-pressed',String(b.dataset.view===sidebarMode));});const sorted=ConversationUI.ordered(library.conversations),pinned=sorted.filter(c=>c.pinned),others=sorted.filter(c=>!c.pinned);const row=c=>'<div class="history-row '+(c.id===state.id?'current-conversation':'')+'"><button class="history-item" data-conversation="'+escape(c.id)+'"><span>'+escape(c.title||'新对话')+'</span>'+(map?'<small>'+c.questions.length+' 个问题 · 打开地图 ↗</small>':'')+'</button><button class="conversation-more" data-conversation-menu="'+escape(c.id)+'" aria-label="管理对话：'+escape(c.title||'新对话')+'">⋯</button></div>';const pinIcon='<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m8 3 8 0-1 6 4 4v2H5v-2l4-4-1-6ZM12 15v7"/></svg>';$('#historyList').innerHTML=(pinned.length?'<section class="history-group pinned-group" aria-label="置顶对话"><h3>'+pinIcon+' 置顶 <small>'+pinned.length+'</small></h3>'+pinned.map(row).join('')+'</section>':'')+(others.length?'<section class="history-group regular-group" aria-label="其他对话"><h3>'+(pinned.length?'其他对话':'全部对话')+' <small>'+others.length+'</small></h3>'+others.map(row).join('')+'</section>':'');}
