$('#confirmDelete').onclick=()=>{if(busy||!selected)return;const index=state.questions.findIndex(q=>q.id===selected.id);if(index<0)return;const question=state.questions[index];const linkedFrom=state.questions.filter(q=>q.links.includes(question.id)).map(q=>q.id);state.deletedQuestions=state.deletedQuestions||[];state.deletedQuestions.push({question,index,linkedFrom});state.questions.splice(index,1);for(const q of state.questions)q.links=q.links.filter(id=>id!==question.id);selected=null;$('#deletePrompt').hidden=true;$('#detail').close();QuestionGraph.reset();save();renderMessages();renderMap();toast('已删除问题，原始对话保留，可撤销');};
